photoobj_canonical.body_sql:
SELECT
  /* primary id */
  p.objid::bigint AS objid,

  /* celestial coords - pass through as double precision */
  p.ra::double precision AS ra,
  p.dec::double precision AS dec,

  /* photometric type code - null-normalize to integer */
  (CASE WHEN p.type IS NOT NULL THEN p.type::integer ELSE NULL END) AS type,

  /* observation identifiers - keep original types, null-normalize */
  (CASE WHEN p.run IS NOT NULL THEN p.run::integer ELSE NULL END) AS run,
  (CASE WHEN p.field IS NOT NULL THEN p.field::integer ELSE NULL END) AS field,

  /* clean flag - keep as integer (null if missing) */
  (CASE WHEN p.clean IS NOT NULL THEN p.clean::integer ELSE NULL END) AS clean,

  /* basic photometry - null-normalize to real */
  (CASE WHEN p.u IS NOT NULL THEN p.u::real ELSE NULL END) AS u,
  (CASE WHEN p.g IS NOT NULL THEN p.g::real ELSE NULL END) AS g,
  (CASE WHEN p.r IS NOT NULL THEN p.r::real ELSE NULL END) AS r,
  (CASE WHEN p.i IS NOT NULL THEN p.i::real ELSE NULL END) AS i,
  (CASE WHEN p.z IS NOT NULL THEN p.z::real ELSE NULL END) AS z
FROM
  /* Use the canonical/basic photoobj relation if available; otherwise fall back to photoobj */
  /* Lifted literal: name 'photoobj_basic' is preferred view; if not present, underlying table 'photoobj' matches schema. */
  photoobj_basic p
